<body>
  <!-- Button to open the modal dialog -->
  <button id="chatbot-btn">Start Chatbot</button>

  <!-- Modal dialog box -->
  <div id="chatbot-modal" class="modal">
    <!-- Modal content -->
    <div class="modal-content">
      <h2>Chatbot Conversation</h2>
      <div id="chat-log"></div>
      <form id="chat-form">
        <input type="text" id="chat-input" placeholder="Type a message...">
